#include "stdafx.h"#include "Queue.h"#include "..\Lang.h"////~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Структура работы с задвижкойtypedef struct : public SPROLOZ  {  int nValue;  int nType;  COLORREF on,off,fon;  COLORREF colorTrans;  int nText;  } Queue_HsSH;//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Функция отображенияint PaintHsSH(DefinePaint)  {  QueueP(Queue_HsSH);  //  double dValue = 0;  CShHS& sh = (CShHS&)PipeSH;  //  if ( !IsTypeOK )    {	if (p->nText==1)		TransparentRect(hDC,p->mRect,0x00ff00,p->colorTrans);    if ( ::IsMnemoStyle(MNEMO_EDIT) )		TransparentRect( hDC, p->mRect, 0x80ff, p->colorTrans );    //CMyBrush brush( hDC, 0x0080ff );    //brush.Rect( p->mRect );    return 1;    }  //  if ( p->nType == 0 )    {    if ( sh.mOn && p->on != 0xffffffff )      {      TransparentRect( hDC, p->mRect, p->on, p->fon );      //CMyBrush brush( hDC, p->on );      //brush.Rect( p->mRect );      }    else    if ( !sh.mOn && p->off != 0xffffffff )      {      TransparentRect( hDC, p->mRect, p->off, p->fon );      //CMyBrush brush( hDC, p->off );      //brush.Rect( p->mRect );      }    }  else	if ( p->nType == 1 )    {		char szText[64] = "закрыт";		if ( sh.mOn )			lstrcpy(szText,"открыт");		::DrawText( hDC, szText, lstrlen(szText), &p->mRect, DT_SINGLELINE|DT_VCENTER|DT_CENTER );	}	else    if ( p->nType == 2 )    {			if ((sh.mOn)||(p->nText==1))			{				TransparentRect(hDC,p->mRect,0x00ff00,p->colorTrans);			}	}	else	if ( p->nType == 3 )    {		char szText[64] = "не повернуто";		if ( sh.mOn )			lstrcpy(szText,"повернуто");		::DrawText( hDC, szText, lstrlen(szText), &p->mRect, DT_SINGLELINE|DT_VCENTER|DT_CENTER );	}		else	if ( p->nType == 4 )    {		char szText[64] = "не зацеплен";		if ( sh.mOn )			lstrcpy(szText,"в зацеплении");		::DrawText( hDC, szText, lstrlen(szText), &p->mRect, DT_SINGLELINE|DT_VCENTER|DT_CENTER );	}	else	if ( p->nType == 5 )    {		char szText[64] = "ВПУ не зацеплен";		if ( sh.mOn )			lstrcpy(szText,"ВПУ в зацеплении");		::DrawText( hDC, szText, lstrlen(szText), &p->mRect, DT_SINGLELINE|DT_VCENTER|DT_CENTER );	}	else	if ( p->nType == 6 )    {		char szText[64] = "";		if ( sh.mOn )			lstrcpy(szText,"ВПУ в движении");		::DrawText( hDC, szText, lstrlen(szText), &p->mRect, DT_SINGLELINE|DT_VCENTER|DT_CENTER );	}  //  return 1;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void AddHsSH(DefineTegs)  {  //  AddQueueEx(Queue_HsSH);  //  // Код, посылаемый в АРМ  p->btSendType = QUEUE_NO;  // Определение функции вывода  p->paint = &PaintHsSH;  //  p->on  = 0xffffffff;  p->off = 0xffffffff;  p->fon = 0x00ffffff;  p->colorTrans=0xcdcccc;  p->nText=-1;  //  STegObj obj[] =    {    { 'I', "type" , &p->nType },    { 'A', "on"   , &p->on  },    { 'A', "off"  , &p->off },    { 'A', "fon"  , &p->fon },	{ 'A', "clrTrans"  , &p->colorTrans },	{ 'I', "text", &p->nText},    // Дополнительная информация    EXT_QUEUE    };  //  ::ParserObjScn( teg, obj, sizeof(obj)/sizeof(STegObj) );  AddPRSHPipe( def, id_HS, teg[0].value, p, p->nValue );  //  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~